<?php
try {[$from,$to]=report_filter();}catch(RuntimeException $e){echo '<p class="error">'.esc($e->getMessage()).'</p>';return;}
$opening=sql("SELECT COALESCE(SUM(CASE WHEN jenis='masuk' THEN nominal ELSE -nominal END),0) FROM transactions WHERE tanggal < ?",[$from])->fetchColumn();
$totals=sql("SELECT COALESCE(SUM(CASE WHEN jenis='masuk' THEN nominal ELSE 0 END),0) masuk, COALESCE(SUM(CASE WHEN jenis='keluar' THEN nominal ELSE 0 END),0) keluar FROM transactions WHERE tanggal BETWEEN ? AND ?",[$from,$to])->fetch();
$mk=metode_ada()?'metode':"'cash'";
$perMetode=['cash'=>['awal'=>0.0,'masuk'=>0.0,'keluar'=>0.0],'transfer'=>['awal'=>0.0,'masuk'=>0.0,'keluar'=>0.0]];
foreach(sql("SELECT $mk m, COALESCE(SUM(CASE WHEN jenis='masuk' THEN nominal ELSE -nominal END),0) s FROM transactions WHERE tanggal < ? GROUP BY m",[$from]) as $r) if(isset($perMetode[$r['m']])) $perMetode[$r['m']]['awal']=(float)$r['s'];
foreach(sql("SELECT $mk m, COALESCE(SUM(CASE WHEN jenis='masuk' THEN nominal ELSE 0 END),0) a, COALESCE(SUM(CASE WHEN jenis='keluar' THEN nominal ELSE 0 END),0) b FROM transactions WHERE tanggal BETWEEN ? AND ? GROUP BY m",[$from,$to]) as $r) if(isset($perMetode[$r['m']])) {$perMetode[$r['m']]['masuk']=(float)$r['a'];$perMetode[$r['m']]['keluar']=(float)$r['b'];}
$count=(int)sql('SELECT COUNT(*) FROM transactions WHERE tanggal BETWEEN ? AND ?',[$from,$to])->fetchColumn();
$n=max(1,(int)query('n','1'));$pages=max(1,(int)ceil($count/50));$n=min($n,$pages);$offset=($n-1)*50;
$rows=sql('SELECT tanggal,jenis,kategori,'.kolom_kategori_lain().','.kolom_metode().',uraian,nominal FROM transactions WHERE tanggal BETWEEN ? AND ? ORDER BY tanggal,id LIMIT 50 OFFSET '.$offset,[$from,$to]);
?><h1>Laporan Keuangan</h1><section class="card"><form method="get"><input type="hidden" name="page" value="laporan"><div class="formgrid"><label>Dari Tanggal<input type="date" name="dari" value="<?=esc($from)?>" required></label><label>Sampai Tanggal<input type="date" name="sampai" value="<?=esc($to)?>" required></label></div><button>Tampilkan</button> <a href="?<?=esc(http_build_query(['page'=>'laporan','dari'=>$from,'sampai'=>$to,'export'=>'csv']))?>">Unduh seluruh transaksi periode (CSV)</a> <button type="button" onclick="window.print()">Cetak Halaman</button></form></section><div class="grid"><?php foreach(['Saldo awal'=>$opening,'Pemasukan'=>$totals['masuk'],'Pengeluaran'=>$totals['keluar'],'Saldo akhir'=>(float)$opening+(float)$totals['masuk']-(float)$totals['keluar']] as $label=>$value): ?><section class="card"><h3><?=esc($label)?></h3><div class="number"><?=rupiah($value)?></div></section><?php endforeach; ?></div><section class="card"><h2>Rincian per metode pembayaran</h2><p class="muted">Cash dan transfer dipisahkan, supaya mudah dicocokkan dengan uang tunai dan rekening bank.</p><div class="tablewrap"><table><thead><tr><th>Metode</th><th>Saldo awal</th><th>Pemasukan</th><th>Pengeluaran</th><th>Saldo akhir</th></tr></thead><tbody><?php foreach($perMetode as $m=>$x): ?><tr><td><?=esc(label_metode($m))?></td><td><?=rupiah($x['awal'])?></td><td><?=rupiah($x['masuk'])?></td><td><?=rupiah($x['keluar'])?></td><td><?=rupiah($x['awal']+$x['masuk']-$x['keluar'])?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="card"><h2>Periode <?=esc($from)?> s.d. <?=esc($to)?></h2><p><?=$count?> transaksi · Halaman <?=$n?> / <?=$pages?> (maksimal 50 transaksi per halaman cetak)</p><div class="tablewrap"><table><thead><tr><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Metode</th><th>Uraian</th><th>Nominal</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=esc($r['tanggal'])?></td><td><?=esc($r['jenis'])?></td><td><?=esc(label_kategori($r))?></td><td><?=esc(label_metode($r['metode']))?></td><td><?=esc($r['uraian']!==''?$r['uraian']:'-')?></td><td><?=rupiah($r['nominal'])?></td></tr><?php endforeach; ?><?php if(!$count): ?><tr><td colspan="6">Belum ada transaksi pada periode ini.</td></tr><?php endif; ?></tbody></table></div><div class="pager"><?php foreach(['Sebelumnya'=>$n-1,'Berikutnya'=>$n+1] as $label=>$num): if($num>=1 && $num<=$pages): ?><a href="?<?=esc(http_build_query(['page'=>'laporan','dari'=>$from,'sampai'=>$to,'n'=>$num]))?>"><?=esc($label)?></a><?php endif;endforeach; ?></div><p class="muted">Saldo berdasarkan transaksi tercatat, bukan hasil rekonsiliasi kas dan bank.</p></section>